"""CLI client: talks to the portcullis server, converts flags to typed JSON."""

import json
import sys
import tomllib
from pathlib import Path

import requests

DEFAULT_SESSION_FILE = Path.cwd() / ".portcullis-client.toml"


class ClientError(Exception):
    """Raised for client-side usage errors before or during a request."""


def load_session(path):
    """Read token and port from the session file generated by the server."""
    path = Path(path)
    if not path.exists():
        raise ClientError(f"session file not found: {path}")
    with open(path, "rb") as fh:
        data = tomllib.load(fh)
    for key in ("port", "token"):
        if key not in data:
            raise ClientError(f"session file {path} is missing {key!r}")
    return data


def api_base(session):
    """Return the base URL of the server."""
    return f"http://127.0.0.1:{session['port']}"


def api_headers(session):
    """Return headers with the bearer token."""
    return {"Authorization": f"Bearer {session['token']}"}


def convert_value(name, spec, raw):
    """Convert one CLI string to a JSON value using the type from GET docs."""
    ptype = spec.get("type", "string")
    if ptype in ("string", "local_readable_file"):
        return raw
    if ptype == "integer":
        try:
            return int(raw)
        except ValueError:
            raise ClientError(f"--{name}: expected integer, got {raw!r}") from None
    if ptype == "boolean":
        if raw.lower() not in ("true", "false"):
            raise ClientError(f"--{name}: expected true/false, got {raw!r}")
        return raw.lower() == "true"
    # Unknown helper type: pass through as string, server validates.
    return raw


def fetch_docs(session, parts):
    """GET the docs JSON for /, /<group> or /<group>/<command>."""
    url = api_base(session) + ("/" + "/".join(parts) if parts else "/")
    resp = requests.get(url, headers=api_headers(session), timeout=10)
    if resp.status_code != 200:
        raise ClientError(f"server returned {resp.status_code} for {url}: {resp.text.strip()}")
    return resp.json()


def print_help(doc, parts):
    """Pretty-print docs JSON for root, group or command level."""
    if not parts:
        print("Available command groups:")
        for group in doc.get("groups", []):
            print(f"  {group['path']:<20} {group['description']}")
        return
    if len(parts) == 1:
        print(f"{doc.get('group', parts[0])}: {doc.get('description', '')}")
        print("Commands:")
        for cmd in doc.get("commands", []):
            print(f"  {cmd['path']:<32} {cmd['description']}")
        return
    name = " ".join(parts)
    print(f"{name}: {doc.get('description', '')}")
    print(f"Usage: portcullis {name} [--<param> <value> ...]")
    for pname, spec in doc.get("params", {}).items():
        req = "required" if spec.get("required") else "optional"
        print(f"  --{pname} <{spec.get('type')}> ({req})  {spec.get('description', '')}")


def parse_params(tokens):
    """Parse --name value pairs from leftover CLI tokens into a dict."""
    params = {}
    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if not tok.startswith("--"):
            raise ClientError(f"unexpected argument: {tok!r} (params must be --name value)")
        if i + 1 >= len(tokens):
            raise ClientError(f"missing value for {tok!r}")
        params[tok[2:]] = tokens[i + 1]
        i += 2
    return params


def parse_args(argv):
    """Manually parse argv: --session-file, -h/--help anywhere, path, params.

    Returns (session_file, help_mode, path_parts, param_tokens).
    """
    argv = list(argv)
    session_file = DEFAULT_SESSION_FILE
    if "--session-file" in argv:
        idx = argv.index("--session-file")
        if idx + 1 >= len(argv):
            raise ClientError("--session-file requires a value")
        session_file = Path(argv[idx + 1])
        del argv[idx:idx + 2]
    help_mode = "-h" in argv or "--help" in argv
    rest = [a for a in argv if a not in ("-h", "--help")]
    path_parts = []
    for tok in rest:
        if tok.startswith("--"):
            break
        path_parts.append(tok)
    return session_file, help_mode, path_parts, rest[len(path_parts):]


def run_command(session, parts, params):
    """Fetch docs, convert params, POST and stream NDJSON, exit with command's code."""
    docs = fetch_docs(session, parts)
    spec = docs.get("params", {})
    unknown = set(params) - set(spec)
    if unknown:
        raise ClientError(f"unknown parameter(s): {', '.join(sorted(unknown))}")
    for pname, pdef in spec.items():
        if pdef.get("required") and pname not in params:
            raise ClientError(f"missing required parameter: --{pname}")
    payload = {name: convert_value(name, spec[name], value) for name, value in params.items()}

    url = api_base(session) + "/" + "/".join(parts)
    with requests.post(url, json=payload, headers=api_headers(session), stream=True) as resp:
        if resp.status_code != 200:
            raise ClientError(f"server returned {resp.status_code}: {resp.text.strip()}")
        for line in resp.iter_lines():
            if not line:
                continue
            event = json.loads(line)
            if event["type"] == "output":
                sys.stdout.write(event["data"])
                sys.stdout.flush()
            elif event["type"] == "done":
                sys.exit(event["exit_code"])
            elif event["type"] == "error":
                raise ClientError(f"{event.get('code')}: {event.get('message')}")


def main(argv=None):
    """Entry point for the portcullis client command."""
    argv = sys.argv[1:] if argv is None else argv
    try:
        session_file, help_mode, parts, param_tokens = parse_args(argv)
        session = load_session(session_file)
        if help_mode:
            print_help(fetch_docs(session, parts), parts)
            return 0
        if not parts:
            raise ClientError("no command given; try: portcullis -h")
        run_command(session, parts, parse_params(param_tokens))
    except ClientError as exc:
        print(f"portcullis: {exc}", file=sys.stderr)
        return 2
    except requests.ConnectionError:
        print("portcullis: cannot reach the server (is portcullis-server running?)",
              file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    sys.exit(main())
